public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryGetContextRejection(principal, resource, request, out var decision))
            return decision;

        var validPrincipal = principal!;
        var validResource = resource!;
        var validRequest = request!;

        if (TryGetRequestRejection(validPrincipal, validResource, validRequest, out decision))
            return decision;

        var authorization = GetAuthorizationContext(validPrincipal, validResource, validRequest, delegations);

        if (TryGetBreakGlassDecision(validRequest, authorization, out decision))
            return decision;
        if (TryGetResourceRestriction(validResource, validRequest, out decision))
            return decision;
        if (TryGetAuthorizationRejection(validRequest.Action, authorization, out decision))
            return decision;

        var outsideBusinessHours = validRequest.MinuteOfDay < 480 || validRequest.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            authorization.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || validResource.Classification == "restricted");
    }

    private static bool TryGetContextRejection(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision decision)
    {
        if (principal is null || resource is null || request is null)
            return Reject("missing-context", true, out decision);
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Reject("invalid-identity", true, out decision);
        if (principal.Suspended)
            return Reject("principal-suspended", true, out decision);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Reject("tenant-mismatch", true, out decision);

        decision = default!;
        return false;
    }

    private static bool TryGetRequestRejection(
        Principal principal,
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Locked && request.Action != "read")
            return Reject("resource-locked", true, out decision);
        if (request.MinuteOfDay is < 0 or > 1439)
            return Reject("invalid-time", true, out decision);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Reject("challenge-required", true, out decision);

        decision = default!;
        return false;
    }

    private static AuthorizationContext GetAuthorizationContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        return new AuthorizationContext(administrator, operatorRole, auditor, owner, delegated);
    }

    private static bool TryGetBreakGlassDecision(
        AccessRequest request,
        AuthorizationContext authorization,
        out AccessDecision decision)
    {
        if (!request.BreakGlass)
        {
            decision = default!;
            return false;
        }

        decision = !authorization.Administrator || !request.StrongAuthentication
            ? new AccessDecision(false, "invalid-break-glass", true)
            : new AccessDecision(true, "break-glass", true);
        return true;
    }

    private static bool TryGetResourceRestriction(
        Resource resource,
        AccessRequest request,
        out AccessDecision decision)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Reject("strong-authentication-required", true, out decision);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Reject("trusted-network-required", true, out decision);

        decision = default!;
        return false;
    }

    private static bool TryGetAuthorizationRejection(
        string? action,
        AuthorizationContext authorization,
        out AccessDecision decision)
    {
        switch (action)
        {
            case "delete" when !authorization.Administrator:
                return Reject("administrator-required", true, out decision);
            case "write" when !CanWrite(authorization):
                return Reject("write-not-authorised", true, out decision);
            case "read" when !CanRead(authorization):
                return Reject("read-not-authorised", false, out decision);
            case "read":
            case "write":
            case "delete":
                decision = default!;
                return false;
            default:
                return Reject("unknown-action", true, out decision);
        }
    }

    private static bool CanWrite(AuthorizationContext authorization) =>
        authorization.Administrator ||
        authorization.OperatorRole ||
        authorization.Owner ||
        authorization.Delegated;

    private static bool CanRead(AuthorizationContext authorization) =>
        authorization.Administrator ||
        authorization.OperatorRole ||
        authorization.Auditor ||
        authorization.Owner ||
        authorization.Delegated;

    private static bool Reject(string reason, bool requiresAudit, out AccessDecision decision)
    {
        decision = new AccessDecision(false, reason, requiresAudit);
        return true;
    }

    private readonly record struct AuthorizationContext(
        bool Administrator,
        bool OperatorRole,
        bool Auditor,
        bool Owner,
        bool Delegated);
}
